package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
public class WorldModelTest {
 @Test public void nativeLearnedPredictionPlanningAndRecordedRealityAreScoredSeparately() throws Exception {
  var project=Files.createTempDirectory("world-model-proof-");try(var brain=new BrainService(project)){
   var job=BrainServiceTest.await(brain,brain.start(new JSONObject().put("kind","world-model-train")).getString("id"));Files.writeString(Path.of("build/world-model-evidence.json"),job.toString(2));assertEquals(job.optString("reason"),"completed",job.getString("status"));
   assertEquals(72,job.getInt("progress"));assertTrue(job.getJSONObject("worldPredictionEvaluation").toString()+" / "+job.getJSONObject("worldPlanningEvaluation"),job.getBoolean("accepted"));assertTrue(brain.activeWorldModel().getBoolean("available"));assertEquals(47,job.getJSONObject("realityEvaluation").getInt("forecastRows"));assertFalse(job.getJSONObject("realityEvaluation").getBoolean("actionUseAuthorized"));
   assertEquals(32,job.getJSONArray("worldTraining").length());assertEquals(8,job.getJSONArray("worldCalibration").length());assertEquals(16,job.getJSONArray("worldTestEpisodes").length());
   for(String key:new String[]{"worldTraining","worldCalibration","worldTestEpisodes"})for(Object raw:job.getJSONArray(key)){var e=(JSONObject)raw;String prefix=key.equals("worldTraining")?"fit-":key.equals("worldCalibration")?"cal-":"eval-";assertTrue(e.getJSONObject("source").getString("id").startsWith(prefix));for(Object value:e.getJSONArray("transitions")){var t=(JSONObject)value;assertEquals(12,t.getJSONObject("after").getInt("tick")-t.getJSONObject("before").getInt("tick"));assertTrue(Math.abs(t.getDouble("action"))<=.6000001);}}
   var evaluation=job.getJSONObject("worldPredictionEvaluation");double sx=0,sv=0,bx=0,bv=0;int covered=0;for(Object raw:evaluation.getJSONArray("predictions")){var row=(JSONObject)raw;JSONObject actual=row.getJSONObject("actual"),prediction=row.getJSONObject("predicted"),before=row.getJSONObject("before");double ex=prediction.getDouble("x")-actual.getDouble("x"),ev=prediction.getDouble("v")-actual.getDouble("v");sx+=ex*ex;sv+=ev*ev;double baselineV=before.getDouble("v")+row.getDouble("action");bx+=Math.pow(before.getDouble("x")+.05*baselineV-actual.getDouble("x"),2);bv+=Math.pow(baselineV-actual.getDouble("v"),2);if(Math.abs(ex)<=row.getDouble("radiusX")&&Math.abs(ev)<=row.getDouble("radiusV"))covered++;}
   assertEquals(Math.sqrt(sx/256),evaluation.getDouble("positionRmseM"),1e-12);assertEquals(Math.sqrt(sv/256),evaluation.getDouble("velocityRmseMps"),1e-12);assertEquals(Math.sqrt(bx/256),evaluation.getDouble("kinematicPositionRmseM"),1e-12);assertEquals(Math.sqrt(bv/256),evaluation.getDouble("kinematicVelocityRmseMps"),1e-12);assertEquals(covered/256.0,evaluation.getDouble("oneStepBandCoverage"),0);
   var r=job.getJSONObject("realityEvaluation");double realSquares=0,max=0;for(Object raw:r.getJSONArray("rows")){var row=(JSONObject)raw;double error=row.getDouble("passiveFreeForecastM")-row.getDouble("observedM");realSquares+=error*error;max=Math.max(max,Math.abs(error));}assertEquals(Math.sqrt(realSquares/47),r.getDouble("freeRmseM"),1e-12);assertEquals(max,r.getDouble("freeMaxErrorM"),1e-12);assertFalse(r.getBoolean("accepted"));assertEquals(.015,r.getDouble("toleranceM"),0);
  }
 }
 @Test public void imaginationDoesNotMoveBodiesAndLiveModelCommandsReplayAfterRestart() throws Exception {
  var project=Files.createTempDirectory("world-model-live-");String id;double finalX;
  try(var brain=new BrainService(project);var scenes=new SceneStore(project)){
   BrainServiceTest.await(brain,brain.start(new JSONObject().put("kind","world-model-train")).getString("id"));var scene=scenes.save(new JSONObject().put("title","Imagine then act").put("parameters",new JSONObject().put("angleDeg",24).put("friction",.18)));
   var prepared=scenes.worldPrepare(new JSONObject().put("id",scene.getString("id")).put("expectedVersion",1).put("targetM",1.2),brain);id=prepared.getString("id");var before=prepared.getJSONObject("current");var preview=scenes.worldPreview(new JSONObject().put("runId",id).put("expectedTick",0).put("observationSha256",prepared.getJSONObject("worldProgress").getString("observationSha256")));assertTrue(preview.getBoolean("previewOnly"));assertEquals(49,preview.getInt("candidates"));assertEquals(7,preview.getJSONArray("constantActionAlternatives").length());assertTrue(before.similar(scenes.snapshot().getJSONObject("current")));assertEquals(0,scenes.snapshot().getJSONObject("worldProgress").getInt("actions"));
   for(int t=0;t<360;t++){if(t==128)scenes.worldKick(new JSONObject().put("runId",id).put("operationId",java.util.UUID.randomUUID().toString()).put("deltaVelocityMps",.4));scenes.control(new JSONObject().put("action","step"));}
   var run=scenes.runRecord(id);Files.writeString(Path.of("build/world-live-evidence.json"),run.toString(2));assertTrue(run.getJSONObject("worldEvaluation").toString(),run.getJSONObject("worldEvaluation").getBoolean("passed"));assertTrue(run.getJSONArray("worldInnovations").length()>20);finalX=run.getJSONObject("final").getDouble("distanceM");
   scenes.control(new JSONObject().put("action","reset"));var replay=scenes.replay(id);assertTrue(replay.getJSONObject("replayEvaluation").getBoolean("passed"));assertEquals(finalX,replay.getJSONObject("final").getDouble("distanceM"),1e-6);
  }
  try(var brain=new BrainService(project);var scenes=new SceneStore(project)){assertTrue(brain.activeWorldModel().getBoolean("available"));assertEquals(finalX,scenes.runRecord(id).getJSONObject("final").getDouble("distanceM"),0);assertFalse(brain.rollbackWorld(1).getBoolean("available"));assertThrows(IllegalStateException.class,brain::worldForRun);}
 }
 @Test public void stateDomainAndCheckpointBoundsAreEnforcedWithoutInventingPredictions() throws Exception {
  var weights=new double[5][3][7];var model=new fraymus.neural.LearnedDynamics(weights,.01,.1);var context=new fraymus.neural.LearnedDynamics.Context(25,9.81,.1,1);
  assertThrows(IllegalArgumentException.class,()->model.predict(new fraymus.neural.LearnedDynamics.State(0,99,1),0,context));assertThrows(IllegalArgumentException.class,()->model.predict(new fraymus.neural.LearnedDynamics.State(0,0,1),.9,context));assertThrows(IllegalArgumentException.class,()->model.predict(new fraymus.neural.LearnedDynamics.State(0,0,1),0,new fraymus.neural.LearnedDynamics.Context(45,9.81,.1,1)));
  weights[0][0][0]=Double.NaN;assertThrows(IllegalArgumentException.class,()->new fraymus.neural.LearnedDynamics(weights,0,0));
 }
 @Test public void cancelledLearningDoesNotActivateAndRecordedSourceTamperingCannotBecomeSyntheticData() throws Exception {
  var project=Files.createTempDirectory("world-model-cancel-");try(var brain=new BrainService(project)){var job=brain.start(new JSONObject().put("kind","world-model-train"));brain.cancel(job.getString("id"));assertEquals("cancelled",BrainServiceTest.await(brain,job.getString("id")).getString("status"));assertFalse(brain.activeWorldModel().getBoolean("available"));}
  var fake=Files.createTempDirectory("recorded-source-copy-");var folder=fake.resolve("docs/datasets/delfys75-013");Files.createDirectories(folder);for(String name:new String[]{"training.csv","validation.csv","spatial-calibration-frozen.json","provenance.json"})Files.copy(Path.of("../docs/datasets/delfys75-013").resolve(name),folder.resolve(name));Files.writeString(folder.resolve("validation.csv"),"changed");var model=new fraymus.neural.LearnedDynamics(new double[5][3][7],0,0);assertThrows(IllegalStateException.class,()->RealityForecast.evaluate(fake,model));
 }
 @Test public void pausedPreviewRequiresActualStateDigestAndCancelledWorldRemainsStopped() throws Exception {
  var project=Files.createTempDirectory("world-model-fence-");try(var brain=new BrainService(project);var scenes=new SceneStore(project)){
   BrainServiceTest.await(brain,brain.start(new JSONObject().put("kind","world-model-train")).getString("id"));var scene=scenes.save(new JSONObject().put("title","State digest fence"));var prepared=scenes.worldPrepare(new JSONObject().put("id",scene.getString("id")).put("expectedVersion",1).put("targetM",1.2),brain);
   var preview=new JSONObject().put("runId",prepared.getString("id")).put("expectedTick",0).put("observationSha256",prepared.getJSONObject("worldProgress").getString("observationSha256"));scenes.worldPreview(preview);
   var kick=new JSONObject().put("runId",prepared.getString("id")).put("operationId",java.util.UUID.randomUUID().toString()).put("deltaVelocityMps",.4);scenes.worldKick(kick);int count=scenes.snapshot().getJSONObject("worldProgress").getInt("actions");scenes.worldKick(kick);assertEquals(count,scenes.snapshot().getJSONObject("worldProgress").getInt("actions"));assertThrows(IllegalStateException.class,()->scenes.worldPreview(preview));var stopped=scenes.worldCancel(prepared.getString("id"));Thread.sleep(100);assertEquals(stopped.getJSONObject("current").getInt("tick"),scenes.snapshot().getJSONObject("current").getInt("tick"));assertFalse(stopped.getJSONObject("goalEvaluation").getBoolean("passed"));
  }
 }
}
